# Source the environment variables and convert to JSON
env_json="$(grep -v '^#' .env.test | grep -v '^ | awk -F'=' '{
    gsub("/", "\\/", $2)
    gsub("\"", "\\\"", $2)
    if (NR == 1) {
        printf "{\"%s\":\"%s\"", $1, $2
    } else {
        printf ",\"%s\":\"%s\"", $1, $2
    }
} END {
    printf "}\n"
}")"

